/* ---------- Helpers ---------- */
function todosModulosVendedor(){
  return NIVELES_VENDEDOR.flatMap(n => n.modulos.map(m => ({...m, nivelId:n.id, nivelNombre:n.nombre, nivelSlug:n.slug, nivelColor:n.color})));
}
function moduloVendedorPorId(id){
  return todosModulosVendedor().find(m => m.id === id);
}
function nivelVendedorDe(id){
  return NIVELES_VENDEDOR.find(n => n.modulos.some(m => m.id === id));
}
